from _game import tools
L = tools["run_lua"]
print(L("local o={} for _,q in pairs(game.forces.player.platforms) do if q.name:find('Nauvis-Fulgora',1,true) then local w={} for i,r in pairs(q.schedule.records) do local c={} for _,x in pairs(r.wait_conditions or {}) do c[#c+1]=x.type..(x.condition and (':'..tostring(x.condition.first_signal and x.condition.first_signal.name)..x.condition.comparator..tostring(x.condition.constant)) or '')..(x.ticks and (':'..x.ticks) or '')..'/'..tostring(x.compare_type) end w[#w+1]=r.station..'['..table.concat(c,' ')..']' end local inv=q.hub.get_inventory(defines.inventory.hub_main) local it={} for _,x in pairs(inv.get_contents()) do it[#it+1]=x.name..'='..x.count end o[#o+1]=q.index..' '..q.name:sub(-24)..' at '..(q.space_location and q.space_location.name or 'flight')..' paused='..tostring(q.paused)..' state '..q.state..string.char(10)..'   sched '..table.concat(w,' > ')..string.char(10)..'   hub: '..table.concat(it,', ')..' trash '..q.hub.get_inventory(defines.inventory.hub_trash).get_item_count() end end rcon.print(table.concat(o,string.char(10)))"))
